-- PoliticData PostgreSQL / Neon: schema de preparo, sem alterar SQLite.
BEGIN;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leaders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, phone TEXT, region TEXT, neighborhood TEXT, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, nickname TEXT, activity TEXT, electoral_zone TEXT, electoral_section TEXT, address TEXT, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS meetings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,leader_id BIGINT NOT NULL REFERENCES leaders(id) ON DELETE CASCADE, meeting_date TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'reunião',summary TEXT NOT NULL,next_action TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS demands(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,leader_id BIGINT NOT NULL REFERENCES leaders(id) ON DELETE CASCADE,opened_at TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'aberta' CHECK(status IN ('aberta','em andamento','atendida','recusada')),resolution TEXT,resolved_at TEXT,estimated_cost DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(estimated_cost>=0),actual_cost DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(actual_cost>=0),due_date TEXT);
CREATE TABLE IF NOT EXISTS expenses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,leader_id BIGINT REFERENCES leaders(id) ON DELETE SET NULL,expense_date TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount DOUBLE PRECISION NOT NULL CHECK(amount>=0),receipt_ref TEXT,compliance_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,review_status TEXT NOT NULL DEFAULT 'pendente');
CREATE TABLE IF NOT EXISTS contacts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,phone TEXT,neighborhood TEXT,notes TEXT,leader_id BIGINT REFERENCES leaders(id) ON DELETE SET NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS elections(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,election_year INTEGER NOT NULL,round INTEGER NOT NULL DEFAULT 1,office TEXT NOT NULL,municipality TEXT NOT NULL,neighborhood TEXT,zone TEXT,section TEXT,polling_place TEXT,candidate TEXT NOT NULL,votes INTEGER NOT NULL CHECK(votes>=0),eligible INTEGER,turnout INTEGER,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,source TEXT NOT NULL,UNIQUE(election_year,round,office,municipality,zone,section,candidate));
CREATE INDEX IF NOT EXISTS idx_contacts_leader ON contacts(leader_id);
CREATE INDEX IF NOT EXISTS idx_meet_leader ON meetings(leader_id,meeting_date);
CREATE INDEX IF NOT EXISTS idx_demand_leader ON demands(leader_id,status);
CREATE INDEX IF NOT EXISTS idx_vote_geo ON elections(election_year,municipality,zone,section);
COMMIT;
